using System;
using System.Collections.Generic;

namespace Framework.AI.Memory
{
    /// <summary>
    /// 場所ごとの訪問履歴を管理する。
    /// </summary>
    /// <typeparam name="TPosition">場所を識別する型</typeparam>
    /// <remarks>
    /// 位置型には等価性とハッシュ値が変化しない型を使用する。
    /// 巡回先の選択や経路探索は行わない。
    /// </remarks>
    public sealed class SpatialMemory<TPosition>
    {
        /// <summary>
        /// 場所ごとの訪問記録。
        /// </summary>
        private readonly Dictionary<TPosition,
            SpatialMemoryEntry> entries =
            new Dictionary<TPosition,
                SpatialMemoryEntry>();

        /// <summary>
        /// 訪問済みの場所の件数を取得する。
        /// </summary>
        public int VisitedPositionCount => entries.Count;

        /// <summary>
        /// 指定された場所への訪問を記録する。
        /// </summary>
        /// <param name="position">訪問した場所</param>
        /// <param name="timestamp">訪問時刻。単位は秒</param>
        /// <returns>訪問記録の追加または更新に成功した場合はtrue</returns>
        /// <remarks>
        /// 同一地点の同時刻または過去の訪問記録は拒否する。
        /// 訪問回数が最大値に達した場合は最大値を維持する。
        /// </remarks>
        public bool RecordVisit(
            TPosition position,
            double timestamp)
        {
            ValidatePosition(position);
            ValidateTime(timestamp);

            if (entries.TryGetValue(
                position,
                out SpatialMemoryEntry previous))
            {
                // 重複した訪問通知や古い通知を拒否する。
                if (timestamp <= previous.LastVisitedTime)
                {
                    return false;
                }

                int visitCount =
                    previous.VisitCount == int.MaxValue
                    ? int.MaxValue
                    : previous.VisitCount + 1;

                entries[position] =
                    new SpatialMemoryEntry(
                        previous.FirstVisitedTime,
                        timestamp,
                        visitCount);

                return true;
            }

            // 初めて訪問した場所を登録する。
            entries.Add(
                position,
                new SpatialMemoryEntry(
                    timestamp,
                    timestamp,
                    1));

            return true;
        }

        /// <summary>
        /// 指定された場所の訪問記録を取得する。
        /// </summary>
        /// <param name="position">取得対象の場所</param>
        /// <param name="entry">取得した訪問記録</param>
        /// <returns>訪問記録が存在する場合はtrue</returns>
        public bool TryGetEntry(
            TPosition position,
            out SpatialMemoryEntry entry)
        {
            ValidatePosition(position);

            return entries.TryGetValue(
                position,
                out entry);
        }

        /// <summary>
        /// 指定された場所を訪問済みか判定する。
        /// </summary>
        /// <param name="position">判定対象の場所</param>
        /// <returns>訪問済みの場合はtrue</returns>
        public bool HasVisited(TPosition position)
        {
            ValidatePosition(position);

            return entries.ContainsKey(position);
        }

        /// <summary>
        /// 指定された場所の訪問回数を取得する。
        /// </summary>
        /// <param name="position">取得対象の場所</param>
        /// <returns>訪問回数。未訪問の場合は0</returns>
        public int GetVisitCount(TPosition position)
        {
            if (TryGetEntry(
                position,
                out SpatialMemoryEntry entry))
            {
                return entry.VisitCount;
            }

            return 0;
        }

        /// <summary>
        /// 最終訪問からの経過時間を取得する。
        /// </summary>
        /// <param name="position">取得対象の場所</param>
        /// <param name="currentTime">現在時刻。単位は秒</param>
        /// <returns>
        /// 最終訪問からの経過秒数。
        /// 未訪問の場合は正の無限大。
        /// </returns>
        /// <remarks>
        /// 現在時刻が最終訪問時刻より古い場合は0を返す。
        /// </remarks>
        public double GetTimeSinceLastVisit(
            TPosition position,
            double currentTime)
        {
            ValidateTime(currentTime);

            if (!TryGetEntry(
                position,
                out SpatialMemoryEntry entry))
            {
                return double.PositiveInfinity;
            }

            return Math.Max(
                0d,
                currentTime - entry.LastVisitedTime);
        }

        /// <summary>
        /// 指定された場所の未訪問度を取得する。
        /// </summary>
        /// <param name="position">評価対象の場所</param>
        /// <param name="currentTime">現在時刻。単位は秒</param>
        /// <param name="fullScoreDuration">
        /// 未訪問度が1に達するまでの時間。単位は秒。
        /// </param>
        /// <returns>
        /// 0から1の未訪問度。
        /// 未訪問または長期間未訪問の場合は1。
        /// </returns>
        public float GetUnvisitedScore(
            TPosition position,
            double currentTime,
            double fullScoreDuration)
        {
            if (double.IsNaN(fullScoreDuration) ||
                double.IsInfinity(fullScoreDuration) ||
                fullScoreDuration <= 0d)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(fullScoreDuration));
            }

            double elapsed = GetTimeSinceLastVisit(
                position,
                currentTime);

            // 未訪問の場所も最大評価として扱う。
            if (elapsed >= fullScoreDuration)
            {
                return 1f;
            }

            return (float)(
                elapsed / fullScoreDuration);
        }

        /// <summary>
        /// 指定された場所の訪問記録を削除する。
        /// </summary>
        /// <param name="position">削除対象の場所</param>
        /// <returns>削除に成功した場合はtrue</returns>
        public bool Forget(TPosition position)
        {
            ValidatePosition(position);

            return entries.Remove(position);
        }

        /// <summary>
        /// すべての訪問記録を削除する。
        /// </summary>
        public void Clear()
        {
            entries.Clear();
        }

        /// <summary>
        /// 場所の識別子が有効か検証する。
        /// </summary>
        /// <param name="position">検証対象の場所</param>
        /// <exception cref="ArgumentNullException">
        /// 場所の識別子がnullの場合に発生する。
        /// </exception>
        private static void ValidatePosition(
            TPosition position)
        {
            if (position is null)
            {
                throw new ArgumentNullException(
                    nameof(position));
            }
        }

        /// <summary>
        /// 時刻が有効な値であることを検証する。
        /// </summary>
        /// <param name="time">検証対象の時刻。単位は秒</param>
        /// <exception cref="ArgumentOutOfRangeException">
        /// 時刻が有限の非負数ではない場合に発生する。
        /// </exception>
        private static void ValidateTime(double time)
        {
            if (double.IsNaN(time) ||
                double.IsInfinity(time) ||
                time < 0d)
            {
                throw new ArgumentOutOfRangeException(
                    nameof(time));
            }
        }
    }
}
